{
  "name": "find_user_id_by_email",
  "description": "Looks up a user's unique identifier using their email address. Use this API when you need to resolve an email address to a user ID, for instance before performing user-specific operations that require a user ID rather than an email. This API performs an exact lookup; if no user is associated with the provided email, an error message is returned.\n\nParameters:\n- email (string, required): The email address of the user to look up. Providing a malformed email or an email that does not correspond to any existing user will result in an error.",
  "parameter_descriptions": {
    "email": "The email of the user, such as 'something@example.com'."
  }
}

