  }
}

{
  "name": "transfer_to_human_agents",
  "description": "Transfers the current conversation to a human agent. Use this API only when one of the following conditions is met: (1) the user has explicitly requested to speak with a human agent, or (2) the user's issue cannot be resolved using the available tools and policies at your disposal. This API requires a single parameter: 'summary' (string, required), which must contain a concise summary of the user's issue up to this point in the conversation. The summary should accurately capture the nature of the problem, any relevant details the user has provided, and any steps already attempted, so the human agent can continue without requiring the user to repeat themselves. Since this is the only parameter and it is required, every call must include it. Avoid vague or overly brief summaries that would leave the human agent without sufficient context to assist the user.",
  "parameter_descriptions": {
    "summary": "A summary of the user's issue."
  }
}

