{
  "name": "get_item_details",
  "description": "Retrieves the inventory details of a specific item. Use this API when you need to look up detailed information about an individual item, such as its availability, stock levels, or other inventory-related attributes. Do NOT use this API to look up product-level information or when you only have a product ID rather than an item ID, as these are distinct identifiers. This API is not intended for searching, listing, or browsing items; it is strictly for retrieving details of a single, already-known item.

Parameters:
- item_id (string, required): The unique identifier for the item whose inventory details you want to retrieve. This must be a string value (e.g., a numeric string). It is critical to distinguish item IDs from product IDs — they are different concepts and are not interchangeable. Passing a product ID in place of an item ID will likely result in a failed lookup or incorrect results. Ensure you have obtained the correct item-level identifier before calling this API.

Common validation failures and how to avoid them:
- Providing a product ID instead of an item ID: These are separate identifiers. Verify that the ID you are using corresponds to an item, not a product.
- Omitting item_id: This parameter is required and the call will fail without it.
- Passing a non-string value: The item_id must be provided as a string, even if it appears numeric.",
  "parameter_descriptions": {
    "item_id": "The item id, such as '6086499569'. Be careful the item id is different from the product id."
  }
}

{
  "name": "get_product_details",
  "description": "Get the inventory details of a product.",
  "parameter_descriptions": {
    "product_id": "The product id, such as '6086499569'. Be careful the product id is different from the item id."
  }
}

{
  "name": "get_order_details",
  "description": "Retrieves the status and details of an existing order. Use this API when you need to look up information about a specific order, such as its current status, items, shipping details, or other order-related attributes. Do not use this API to create, modify, or cancel orders, nor to search for orders without a known order ID.\n\nParameters:\n- order_id (string, required): The unique identifier for the order. This value must be a string that begins with the '#' character followed by a 'W' and seven digits (e.g., in the format '#W' followed by numeric characters). A common mistake is omitting the leading '#' symbol, which will result in a validation or lookup failure. Ensure the '#' prefix is always included when constructing this parameter.",
  "parameter_descriptions": {
    "order_id": "The order id, such as '#W0000000'. Be careful there is a '#' symbol at the beginning of the order id."
  }
}

{
  "name": "transfer_to_human_agents",
  "description": "Transfer the user to a human agent, with a summary of the user's issue.\n\nOnly transfer if\n -  the user explicitly asks for a human agent\n -  given the policy and the available tools, you cannot solve the user's issue.",
  "parameter_descriptions": {
    "summary": "A summary of the user's issue."
  }
}

{
  "name": "modify_pending_order_address",
  "description": "Modify the shipping address of a pending order.",
  "parameter_descriptions": {}
}

{
  "name": "modify_pending_order_address",
  "description": "Modify the shipping address of a pending order. The agent needs to explain the modification detail and ask for explicit user confirmation (yes/no) to proceed.",
  "parameter_descriptions": {
    "order_id": "The order id, such as '#W0000000'. Be careful there is a '#' symbol at the beginning of the order id.",
    "address1": "The first line of the address, such as '123 Main St'.",
    "address2": "The second line of the address, such as 'Apt 1' or ''.",
    "city": "The city, such as 'San Francisco'.",
    "state": "The state, such as 'CA'.",
    "country": "The country, such as 'USA'.",
    "zip": "The zip code, such as '12345'."
  }
}

{
  "name": "get_user_details",
  "description": "Retrieves detailed information about a specific user, including their associated orders. Use this API when you need to look up a user's profile details or order history given their user ID. Do not use this API for searching users by name, email, or other attributes\u2014it requires an exact user ID. Also do not use this API to modify user data; it is read-only.\n\nParameters:\n- user_id (string, required): The unique identifier for the user to look up. This is a string value typically formatted as a combination of the user's name and a numeric suffix (e.g., a pattern like 'firstname_lastname_123'). The value must be a non-empty string and must exactly match an existing user's ID. Passing a null, empty, or incorrectly formatted user_id will likely result in a validation or not-found error. Ensure the user_id is obtained from a reliable source (such as a prior API response or known reference) to avoid lookup failures due to typos or incorrect identifiers.",
  "parameter_descriptions": {
    "user_id": "The user id, such as 'sara_doe_496'."
  }
}

{
  "name": "modify_user_address",
  "description": "Modify the default address of a user. The agent needs to explain the modification detail and ask for explicit user confirmation (yes/no) to proceed.",
  "parameter_descriptions": {
    "user_id": "The user id, such as 'sara_doe_496'.",
    "address1": "The first line of the address, such as '123 Main St'.",
    "address2": "The second line of the address, such as 'Apt 1' or ''.",
    "city": "The city, such as 'San Francisco'.",
    "state": "The state, such as 'CA'.",
    "country": "The country, such as 'USA'.",
    "zip": "The zip code, such as '12345'."
  }
}

